-- Daily challenges for 2026-11-12: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-11-12. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('cooking-together', 'Cooking Together', 'For anyone who wants more warmth and laughter in the kitchen. Each day is one small way to cook, bake or share a simple meal with family, friends or neighbors, from stirring a pot side by side to passing on a recipe.', 'Connection', 365, array['Relationships', 'Family', 'Food']::text[], 1, '2026-11-12T17:00:00+00:00'::timestamptz),
  ('caring-for-shared-spaces', 'Caring for Shared Spaces', 'For anyone who wants the places we all use to feel a little better. Each day is one small way to look after parks, sidewalks, buses, libraries and other shared spaces, and to make them kinder for the next person.', 'Values', 365, array['Values', 'Habits']::text[], 1, '2026-11-12T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('cooking-together', 'caring-for-shared-spaces');

