  ('caring-for-shared-spaces', 12, 'Shovel your own sidewalk at an easy pace after the next snowfall, making a path wide enough for a stroller or wheelchair.'),
  ('caring-for-shared-spaces', 13, 'Wipe down the bench or machine you used at the gym, including the handles, before you walk away.'),
  ('caring-for-shared-spaces', 14, 'Check the office fridge for your own leftovers and take home anything that is past its best.'),
  ('caring-for-shared-spaces', 15, 'Bring one book you enjoyed to a little free library and tuck a short note inside for the next reader.'),
  ('caring-for-shared-spaces', 16, 'Stay on the marked trail today, even where a shortcut looks tempting, so the plants beside it can keep growing.'),
  ('caring-for-shared-spaces', 17, 'Sprinkle sand or ice melt on your front walk on an icy winter morning, so the mail carrier and neighbors do not slip.'),
  ('caring-for-shared-spaces', 18, 'Push your chair back under the table when you leave a cafe, library or waiting room today.'),
  ('caring-for-shared-spaces', 19, 'Label your container with your name and the date before it goes in the shared fridge.'),
